package com.renthouse.billing;
import com.renthouse.common.api.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1") public class BillingController{private final BillingService s;public BillingController(BillingService s){this.s=s;}@PostMapping("/landlord/contracts/{contractId}/bills")ApiResponse<BillView>create(@PathVariable long contractId,@RequestBody @Valid Create r){return ApiResponse.ok(s.create(contractId,new BillingService.Create(r.billType(),r.periodStart(),r.periodEnd(),r.amountCent(),r.dueDate(),r.remark())));}@GetMapping("/bills")ApiResponse<PageResponse<BillView>>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.list(page,size));}@PostMapping("/tenant/bills/{id}/payment-reports")ApiResponse<BillView>report(@PathVariable long id,@RequestBody @Valid Report r){return ApiResponse.ok(s.report(id,new BillingService.Report(r.voucherUrl(),r.amountCent(),r.paidAt(),r.note())));}@PostMapping("/landlord/bills/{id}/verify")ApiResponse<BillView>verify(@PathVariable long id,@RequestBody @Valid Verify r){return ApiResponse.ok(s.verify(id,r.approved()));}public record Create(@NotBlank String billType,LocalDate periodStart,LocalDate periodEnd,@Positive int amountCent,@NotNull LocalDate dueDate,String remark){}public record Report(String voucherUrl,@Positive int amountCent,@NotNull LocalDateTime paidAt,String note){}public record Verify(boolean approved){}}
